/**
 * React 19 made `ref` a plain prop, so composition is the only thing left to
 * write: a part that needs the node for itself must still hand it to whoever put
 * a ref on the element.
 *
 * The composed callback returns a cleanup, which is React 19's protocol: a ref
 * that returned its own cleanup is torn down with it, and one that did not is
 * detached the old way, with a `null` call. Mixing the two is what makes this
 * worth a file — an observer installed in a consumer's ref callback would
 * otherwise leak, or be cleaned twice.
 */

import type { Ref } from "react";

// biome-ignore lint/suspicious/noConfusingVoidType: React's own RefCallback return type.
type RefCleanup = VoidFunction | void;

function assign<T>(ref: Ref<T> | undefined, node: T | null): RefCleanup {
  if (ref == null) return;
  if (typeof ref === "function") return ref(node) as RefCleanup;
  (ref as { current: T | null }).current = node;
}

export function composeRefs<T>(
  ...refs: readonly (Ref<T> | undefined)[]
): (node: T | null) => VoidFunction {
  return (node: T | null): VoidFunction => {
    const cleanups = refs.map((ref) => {
      const cleanup = assign(ref, node);
      return typeof cleanup === "function" ? cleanup : (): void => void assign(ref, null);
    });
    return (): void => {
      for (let index = cleanups.length - 1; index >= 0; index--) cleanups[index]?.();
    };
  };
}

/**
 * The shared vocabulary of the composed layer — types only, not one value.
 *
 * A composed component (`<Select options={…}/>`) is a pure function from its props
 * to the parts a consumer would otherwise place by hand: no state, no prop getter
 * re-implemented, no node that is not a part. What every such module shares is a handful of entry shapes, and they
 * live here so that no component invents a second spelling of the same idea.
 *
 * Everything below is erased at emit — `isolatedDeclarations` annotates it and
 * nothing bundles it — which is why this module has no budget line and cannot
 * grow one: the day it holds a value, it becomes a shared module every composed
 * layer pays for, and it has to move to a line of its own.
 */

import type { MouseEvent, ReactElement, ReactNode } from "react";

/** The two fields no machine owns: the leading track, and the consumer's payload. */
export interface ComposedDecoration<Meta = never> {
  /**
   * The single leading track, shared with the selection checkmark — never a second
   * column. The sheet reserves it once per surface (`data-has-symbols`, beside
   * `data-has-selection`), so a row with no glyph keeps its label aligned.
   */
  readonly icon?: ReactNode;
  /** Handed back untouched to `render*`. Erased at emit, so it costs nothing. */
  readonly meta?: Meta | undefined;
}

/**
 * A labelled group. `id` is required rather than defaulted: the part's own `label`
 * is a boolean flag (`SelectItemGroupProps.label`, `MenuItemGroupProps.label`)
 * whose `aria-labelledby` points at the label part, so the composed layer has to
 * render that part *and* pin the key — written blind the attribute is a dead IDREF
 * and a nameless group at once. A pinned key is also what lets the markup parity
 * test compare the two forms to the character.
 */
export interface ComposedGroup<Entry> {
  readonly id: string;
  readonly label: string;
  readonly options: readonly Entry[];
}

/** Structural narrowing — `"separator" in entry`. No `kind` field anywhere. */
export interface ComposedSeparator {
  readonly separator: true;
}

/**
 * A surface action: a button the library places, whose event belongs to it because
 * the part has none of its own. Dialog actions, never menu items — a menu's
 * selection is `onSelect` on the root, and a handler per item would be a name the
 * machine does not have.
 */
export interface ComposedAction {
  readonly label: string;
  /**
   * Handed the event, because the contract the layer publishes for this field is
   * about the event: it lands on the button's `onClick`, runs before the machine's
   * own handler, and a `preventDefault()` inside it keeps the surface open — which
   * is what an action that awaits a request needs. Declared `() => void` the
   * sentence was unwriteable rather than merely undocumented: TypeScript refuses a
   * callback that names a parameter its target has none of, so the one form the
   * JSDoc asks for was the one form that would not compile. It is also the shape
   * every other `onPress` in this library already has (`ButtonPressDetails`,
   * `LinkMachineProps.onPress`), which is the second reason it is not a widening of
   * convenience.
   */
  readonly onPress?: ((event: MouseEvent<HTMLButtonElement>) => void) | undefined;
  readonly destructive?: boolean | undefined;
  readonly cancel?: boolean | undefined;
}

/**
 * The substitution slot of a trigger: an ELEMENT, handed to the part's `render`,
 * never placed as its children. `SelectTrigger` and `MenuTrigger` render a
 * `<button>`; a button inside a button is `nested-interactive`.
 */
export type ComposedTrigger = ReactElement;

/**
 * Most parts are the same eight lines: read the api from the component's context,
 * hand its prop getter to `useRender`, let the consumer's own props and `render`
 * through. A component with eight parts should not restate that eight times —
 * what differs is the getter and the default element, so those are the arguments.
 *
 * Roots keep their own function: they own the machine, and several of them infer
 * something from what they are about to render.
 */

import type { ComponentPropsWithRef, ElementType, ReactNode } from "react";
import type { PartContext } from "./part-context";
import { type RenderableProps, useRender } from "./use-render";

/**
 * Everything the element accepts, plus composition. `Own` is the machine's own
 * props: a root declares them itself, and the element's versions of `id`, `dir`
 * or `defaultValue` have to step aside rather than clash — they mean something
 * different here (`id` is the scope id, not the DOM one).
 */
export type PartProps<E extends ElementType = "div", Own = unknown> = RenderableProps &
  Omit<ComponentPropsWithRef<E>, "children" | keyof Own> & {
    readonly children?: ReactNode;
  };

export interface PartOptions<Api> {
  /** Named in the error when the part is rendered outside its root. */
  readonly name: string;
  readonly element: ElementType;
  props(api: Api): object;
}

export function createPart<Api, E extends ElementType = "div">(
  context: PartContext<Api>,
  options: PartOptions<Api>,
): (props: PartProps<E>) => ReactNode {
  return function Part(props: PartProps<E>): ReactNode {
    const { render, asChild, children, ...elementProps } = props;
    const api = context.usePart(options.name);

    return useRender({
      render,
      asChild,
      element: options.element,
      props: options.props(api),
      elementProps,
      children,
    });
  };
}

/**
 * Where the tree lives — a document, a shadow root, an iframe — and what it
 * resolves to: `{ dir, locale, density, reducedMotion }`.
 *
 * The provider renders no element of its own. Density and theme are attributes an
 * app puts on its own markup (they are settable per subtree, that is the styles
 * contract), and a wrapper `<div>` here would break every grid and flex layout it
 * landed in. What it does instead is watch those attributes and hand the resolved
 * context down, with the same resolution order the styles layer uses: attributes
 * first, media queries second.
 *
 * Given a `rootNode`, it also tells the input layer which document to listen to,
 * so a `NavProvider` goes below it, never above.
 */

import {
  defaultEnvironment,
  type EnvironmentContext,
  type EnvironmentOverrides,
  type RootNode,
  resolveEnvironment,
  trackEnvironment,
} from "@standarui/core";
import { createContext, type ReactNode, useContext, useEffect, useMemo, useState } from "react";
import { NavDocumentProvider } from "./nav";

interface EnvironmentValue {
  readonly getRootNode: (() => RootNode) | undefined;
  readonly environment: EnvironmentContext;
}

const EnvironmentReactContext = createContext<EnvironmentValue | null>(null);

export interface EnvironmentProviderProps extends EnvironmentOverrides {
  readonly rootNode?: RootNode | (() => RootNode) | undefined;
  readonly children?: ReactNode;
}

export function EnvironmentProvider(props: EnvironmentProviderProps): ReactNode {
  const { rootNode, dir, locale, density, motion, reducedMotion, children } = props;

  const getRootNode = useMemo((): (() => RootNode) | undefined => {
    if (rootNode === undefined) return undefined;
    return typeof rootNode === "function" ? rootNode : (): RootNode => rootNode;
  }, [rootNode]);

  // The server and the first client render agree on this: overrides only, no
  // platform read, which is what `resolveEnvironment(null, …)` is for.
  const [environment, setEnvironment] = useState<EnvironmentContext>(() =>
    resolveEnvironment(null, { dir, locale, density, motion, reducedMotion }),
  );

  useEffect(() => {
    const overrides: EnvironmentOverrides = { dir, locale, density, motion, reducedMotion };
    const root = getRootNode?.() ?? document;
    const doc = root.ownerDocument ?? (root as Document);
    const node = doc.documentElement;
    setEnvironment(resolveEnvironment(node, overrides));
    return trackEnvironment(node, { ...overrides, onChange: setEnvironment });
  }, [getRootNode, dir, locale, density, motion, reducedMotion]);

  const value = useMemo<EnvironmentValue>(
    () => ({ getRootNode, environment }),
    [getRootNode, environment],
  );

  const getDocument = useMemo(
    (): (() => Document) | undefined =>
      getRootNode === undefined
        ? undefined
        : (): Document => {
            const root = getRootNode();
            return root.ownerDocument ?? (root as Document);
          },
    [getRootNode],
  );

  return (
    <EnvironmentReactContext.Provider value={value}>
      {getDocument === undefined ? (
        children
      ) : (
        <NavDocumentProvider doc={getDocument}>{children}</NavDocumentProvider>
      )}
    </EnvironmentReactContext.Provider>
  );
}

export function useEnvironment(): EnvironmentContext {
  return useContext(EnvironmentReactContext)?.environment ?? defaultEnvironment;
}

/**
 * `undefined` when no provider is mounted, and that is the useful answer: the
 * core's `Scope` falls back to the document on its own, and passing a
 * `getRootNode` that returns `document` would defeat nothing but readability.
 */
export function useRootNode(): (() => RootNode) | undefined {
  return useContext(EnvironmentReactContext)?.getRootNode;
}

/** The document the tree belongs to. Effects only — it reads the DOM. */
export function useDocument(): () => Document {
  const getRootNode = useRootNode();
  return useMemo(
    () => (): Document => {
      const root = getRootNode?.() ?? document;
      return root.ownerDocument ?? (root as Document);
    },
    [getRootNode],
  );
}

/**
 * The context a control reads to find the field it sits in — deliberately *not*
 * inside the field component's folder.
 *
 * A checkbox that imported `components/field/field` to reach this would drag the
 * field's machine, its five parts and its DOM helpers into every bundle that has
 * a checkbox in it. Measured: 0,26 kB on a wrapper budgeted at 1 kB. The context
 * is the only thing the two sides share, so the context is what lives apart.
 */

import { createPartContext, type PartContext } from "./part-context";

/**
 * The shape a control needs, plus the getters the field's own parts read. Stated
 * structurally rather than imported: `FieldApi` lives in the component, and
 * importing it here would put the dependency back the way it came.
 *
 * The getters are `object` because that is all `useRender` asks of them; the
 * field's real api, which returns React's own prop types, satisfies it.
 */
export interface FieldContextValue {
  readonly invalid: boolean;
  readonly disabled: boolean;
  readonly required: boolean;
  readonly readOnly: boolean;
  readonly controlProps: {
    readonly id: string;
    readonly "aria-describedby": string | undefined;
  };
  /** The label's id for a control `<label for>` cannot name; `undefined` if none. */
  readonly labelId: string | undefined;
  getLabelProps(): object;
  getRequiredIndicatorProps(): object;
  getHelperTextProps(): object;
  getErrorTextProps(): object;
}

export const FieldContext: PartContext<FieldContextValue> = createPartContext("Field");

/**
 * `null` outside a field, which is what lets every control work on its own.
 */
export function useFieldContext(): FieldContextValue | null {
  return FieldContext.useOptional();
}

export interface FieldInheritable {
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly describedBy?: string | undefined;
  readonly labelledBy?: string | undefined;
}

/**
 * What a control inherits from its field, handed to the machine as props rather
 * than merged over its output: merging would let a field's `disabled: false`
 * clobber a control that disabled itself, and the control's id has to reach the
 * machine anyway for `label[for]` to point at the right element.
 *
 * `??` and not `||`: a control that explicitly says `invalid={false}` inside an
 * invalid field means it, and the field must not talk over it.
 */
export function inheritFromField<T extends FieldInheritable>(
  props: T,
  field: FieldContextValue | null,
): T {
  if (field === null) return props;
  return {
    ...props,
    disabled: props.disabled ?? field.disabled,
    invalid: props.invalid ?? field.invalid,
    readOnly: props.readOnly ?? field.readOnly,
    required: props.required ?? field.required,
    describedBy: props.describedBy ?? field.controlProps["aria-describedby"],
    // Only a control that `<label for>` cannot name reads this — the labelable
    // ones take `controlProps.id` and are named by the label itself. Handing it
    // to every control would be harmless but redundant; handing it to none left
    // `role="slider"` with no name at all.
    labelledBy: props.labelledBy ?? field.labelId,
  };
}

export type { Density, InputModality, IntentEvent } from "@standarui/core";
export { composeRefs } from "./compose-refs";
export type { ComposedAction, ComposedTrigger } from "./composed";
export type { PartProps } from "./create-part";
export {
  EnvironmentProvider,
  type EnvironmentProviderProps,
  useDocument,
  useEnvironment,
  useRootNode,
} from "./environment";
export { StandaruiNavProvider } from "./nav";
export { normalizeProps, type ReactPropTypes } from "./normalize-props";
export { Portal, type PortalProps } from "./portal";
export {
  Presence,
  type PresenceApi,
  type PresenceProps,
  type UsePresenceOptions,
  usePresence,
} from "./presence";
export { createReactivity, type ReactivityHandle, useReactivity } from "./reactivity";
export { type MachineRuntimeProps, type UseMachineProps, useMachine } from "./use-machine";
export {
  type RenderableProps,
  type RenderFunction,
  type RenderOptions,
  type RenderProp,
  useRender,
} from "./use-render";
export { useSafeLayoutEffect } from "./use-safe-layout-effect";

/**
 * Which layer a portalled surface was opened from — the one thing a dialog, a
 * popover, a menu and a tooltip have to be able to tell each other, and the only
 * thing.
 *
 * Once two surfaces are portalled they are DOM siblings, so `contains` cannot see
 * that one belongs to the other and parenthood has to be *declared*
 * (`layer-stack.ts` chains on the declaration, never on containment). The dialog
 * declared it through a context private to its own module, which works exactly as
 * long as the outer surface and the inner one are the same component. A popover
 * inside a dialog had no path to that context: it would register as a root layer,
 * and a press inside it would read as an interaction outside the dialog and take
 * the dialog down with it.
 *
 * So the parenthood lives here instead of in any one component's folder — same
 * reason as `field-context`, and the same shape. A surface provides it; a surface
 * reads it; nothing else in the library knows it exists.
 */

import { type ReactNode, useMemo } from "react";
import { createPartContext } from "./part-context";

interface LayerContextValue {
  /**
   * The id of the *surface*, not of the trigger that opens it. A trigger sits in
   * the layer above the one it opens, so naming it here would chain the stack one
   * link short.
   */
  readonly layerId: string;
}

const LayerContext = createPartContext<LayerContextValue>("Layer");

export interface LayerProviderProps {
  readonly layerId: string;
  readonly children?: ReactNode;
}

/**
 * Wraps a surface's subtree, including the parts rendered through its portal.
 * Memoised on the id so the identity is as stable as the layer is: a surface's
 * own context value changes on every render because it carries the api, and a
 * nested surface has no business re-rendering for that.
 */
export function LayerProvider({ layerId, children }: LayerProviderProps): ReactNode {
  const value = useMemo(() => ({ layerId }), [layerId]);
  return <LayerContext.Provider value={value}>{children}</LayerContext.Provider>;
}

/** `undefined` at the top level — which is how a surface knows it is a root layer. */
export function useParentLayerId(): string | undefined {
  return LayerContext.useOptional()?.layerId;
}

/**
 * The one place React's dialect is spoken. `connect` returns plain DOM — `class`,
 * `for`, `onFocusIn` — and every adapter translates once, at this boundary; this
 * file is deliberately excluded from the "an adapter over 500 lines is an
 * architecture bug" count, because it is a dictionary, not logic.
 *
 * `onFocusIn` → `onFocus` is a rename, not an approximation: React's synthetic
 * focus events are `focusin`/`focusout` underneath, so they bubble exactly like
 * the DOM events the core meant.
 *
 * One entry is not a rename and cannot be: `hidden="until-found"` is a value
 * react-dom overwrites rather than a name it spells differently, so it is the
 * one place here that installs behaviour instead of translating a key. Its
 * reasoning is on `writeHiddenUntilFound` below.
 */

import {
  type AnyProps,
  createNormalizer,
  type NormalizeProps,
  type PropTypes,
} from "@standarui/core";
import type { JSX } from "react";

export interface ReactPropTypes extends PropTypes {
  element: JSX.IntrinsicElements["div"];
  a: JSX.IntrinsicElements["a"];
  button: JSX.IntrinsicElements["button"];
  input: JSX.IntrinsicElements["input"];
  label: JSX.IntrinsicElements["label"];
  output: JSX.IntrinsicElements["output"];
  select: JSX.IntrinsicElements["select"];
  textarea: JSX.IntrinsicElements["textarea"];
  img: JSX.IntrinsicElements["img"];
  svg: JSX.IntrinsicElements["svg"];
  circle: JSX.IntrinsicElements["circle"];
  path: JSX.IntrinsicElements["path"];
}

/** Custom properties keep their dashes; React applies them verbatim. */
function toCamelCase(property: string): string {
  if (property.startsWith("--")) return property;
  return property.replace(/-([a-z])/g, (_match, letter: string) => letter.toUpperCase());
}

function parseStyle(style: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const declaration of style.split(";")) {
    const separator = declaration.indexOf(":");
    if (separator === -1) continue;
    const property = declaration.slice(0, separator).trim();
    if (property !== "") result[toCamelCase(property)] = declaration.slice(separator + 1).trim();
  }
  return result;
}

function toReactStyle(style: unknown): Record<string, unknown> | undefined {
  if (typeof style === "string") return parseStyle(style);
  if (typeof style !== "object" || style === null) return undefined;
  const result: Record<string, unknown> = {};
  for (const [property, value] of Object.entries(style)) {
    if (value === undefined) continue;
    result[toCamelCase(property)] = value;
  }
  return result;
}

/**
 * The one attribute value React refuses to carry. `hidden` sits on react-dom's
 * hard-coded boolean list (`setProp`, react-dom-client 19.2), where every truthy
 * value is written as `hidden=""` — so the keyword, which is the whole of the
 * accordion's find-in-page contract, was destroyed on its way to the DOM. There
 * is no prop spelling that escapes it: the switch matches the literal key, and
 * any other casing draws React's "Invalid DOM property" error in dev.
 *
 * So React keeps owning the attribute's *lifecycle* — it is still handed
 * `hidden: true`, which is what the server renders and what hydration then
 * matches, and which is the write it removes when the panel opens — and the
 * keyword is put back on the node by a callback ref. React attaches refs in the
 * layout phase, after the mutation that just wrote `hidden=""`, so the write
 * always lands last within its own commit.
 *
 * The identity is module-level on purpose. React re-runs a callback ref only
 * when the identity changes or when the ref appears or disappears, and this one
 * appears on exactly the commits where the keyword is wanted and disappears on
 * the ones where React takes the attribute off. It therefore fires once per
 * transition and never churns on the renders in between.
 *
 * Known limit: a consumer's own `ref` on the same part wins in `mergeProps` and
 * takes this one's place. The panel then keeps a plain `hidden` — still hidden,
 * still animated, only no longer findable by Ctrl+F.
 */
const UNTIL_FOUND = "until-found";

function writeHiddenUntilFound(node: Element | null): void {
  node?.setAttribute("hidden", UNTIL_FOUND);
}

const RENAMED: Readonly<Record<string, string>> = {
  class: "className",
  for: "htmlFor",
  onFocusIn: "onFocus",
  onFocusOut: "onBlur",
  autofocus: "autoFocus",
};

export const normalizeProps: NormalizeProps<ReactPropTypes> = createNormalizer<ReactPropTypes>(
  (props: AnyProps): AnyProps => {
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(props)) {
      // An explicit `undefined` is dropped rather than forwarded: React would
      // treat `checked: undefined` as "uncontrolled" and warn about the switch.
      if (value === undefined) continue;
      if (key === "style") {
        result.style = toReactStyle(value);
        continue;
      }
      if (key === "hidden" && value === UNTIL_FOUND) {
        result.hidden = true;
        result.ref = writeHiddenUntilFound;
        continue;
      }
      result[RENAMED[key] ?? key] = value;
    }
    return result;
  },
);

/**
 * A component's parts share one thing: the api its root connected. This is that
 * context, with the error message a consumer actually needs when they render a
 * part outside its root.
 *
 * Not exported from the package root — it is component plumbing, and a consumer
 * writing their own component has `useMachine` and `connect`, which is the same
 * thing without the indirection.
 */

import { invariant } from "@standarui/core";
import { createContext, type ReactNode, useContext } from "react";

export interface PartContext<T> {
  Provider(props: { readonly value: T; readonly children: ReactNode }): ReactNode;
  /** `part` is the component name to name in the error, not a lookup key. */
  usePart(part: string): T;
  /**
   * For the contexts a component may legitimately be outside of — a field wraps
   * a control, but a control on its own is not a mistake.
   */
  useOptional(): T | null;
}

export function createPartContext<T>(component: string): PartContext<T> {
  const Context = createContext<T | null>(null);

  function Provider({ value, children }: { value: T; children: ReactNode }): ReactNode {
    return <Context.Provider value={value}>{children}</Context.Provider>;
  }

  function usePart(part: string): T {
    const value = useContext(Context);
    invariant(value !== null, `<${part}> must be rendered inside <${component}Root>`);
    return value;
  }

  function useOptional(): T | null {
    return useContext(Context);
  }

  return { Provider, usePart, useOptional };
}

/**
 * The core never portals — that is rendering, so it belongs to the adapter
 * (research/core.md §5, piège 2). What the core does instead is make portalling
 * safe: outside-clicks are resolved through the logical layer stack rather than
 * `element.contains`, and Tab is proxied across the portal boundary.
 *
 * **The container is resolved during the render on a client mount, and one commit
 * later while hydrating.** The first half is the original rule and it holds:
 * deferring unconditionally renders nothing on the first pass, and a machine whose
 * surface is portalled then starts against an empty document — the interpreter
 * installs a state's effects in the layout effect of the commit that entered the
 * state, every one of them looks its node up by id, and a node that arrives one
 * commit later finds the focus trap, the dismissable layer and the scroll lock all
 * installed against nothing, with nothing to re-install them. Measured, not
 * feared: deferring in every case failed 27 tests across the eight portalled
 * components.
 *
 * The second half is a correction. What used to stand here — "React never hydrates
 * through a portal, so resolving early costs no mismatch" — was wrong, and the
 * documentation site is where it showed. `select` and `toast`, the two surfaces a
 * page ships *rendered while closed*, logged React #418 on every load: the server
 * has no document and rendered nothing, the client resolved the container in that
 * same first pass and rendered a portal. Trees that differ by a node differ in
 * `useId` too — the markup carried `…R_2_:trigger` where the client wanted
 * `…R_1_:positioner`.
 *
 * `useSyncExternalStore` tells the two situations apart, and no other hook does:
 * React reads `getServerSnapshot` for a tree it is hydrating and `getSnapshot` for
 * one mounted fresh. So a client mount keeps the immediate resolution it always
 * had, and a hydrating tree renders `null`, agrees with the server, then picks the
 * container up in the layout effect of that same commit — before the paint.
 *
 * What is left is inherent to the boundary: a surface that hydrates *already open*
 * still has one commit in which its machine's effects find no node. No portal can
 * be server-rendered, so no arrangement of this file closes that window.
 */

import { type ReactNode, useState, useSyncExternalStore } from "react";
import { createPortal } from "react-dom";
import { useDocument } from "./environment";
import { useSafeLayoutEffect } from "./use-safe-layout-effect";

function unsubscribe(): void {}

function subscribe(): () => void {
  return unsubscribe;
}

function getClientSnapshot(): boolean {
  return false;
}

function getServerSnapshot(): boolean {
  return true;
}

/**
 * True for the SSR render and for the hydration render that has to match it; false
 * for a tree mounted fresh on the client. `useSyncExternalStore` is the only hook
 * that tells the two apart — React reads `getServerSnapshot` for a hydrating tree
 * and `getSnapshot` for one mounted fresh.
 */
export function useHydrating(): boolean {
  return useSyncExternalStore(subscribe, getClientSnapshot, getServerSnapshot);
}

export interface PortalProps {
  readonly children?: ReactNode;
  /** Defaults to the body of the nearest root node. */
  readonly container?: Element | null | (() => Element | null) | undefined;
  /** Renders in place instead — the escape hatch for a nested-layout case. */
  readonly disabled?: boolean | undefined;
}

type Container = PortalProps["container"];

function resolve(container: Container): Element | null {
  return (typeof container === "function" ? container() : container) ?? null;
}

export function Portal(props: PortalProps): ReactNode {
  const { children, container, disabled } = props;
  const getDocument = useDocument();
  const hydrating = useHydrating();

  const [mountNode, setMountNode] = useState<Element | null>(() => {
    if (hydrating || disabled === true || typeof document === "undefined") return null;
    const resolved = resolve(container);
    // A container the consumer named but has not mounted yet waits for the effect.
    // Falling back to the body would put the subtree in the wrong place for a
    // commit, which is worse than the frame it costs to be right.
    if (resolved === null && container !== undefined) return null;
    return resolved ?? getDocument().body;
  });

  useSafeLayoutEffect(() => {
    if (disabled === true) return;
    setMountNode(resolve(container) ?? getDocument().body);
  }, [container, disabled, getDocument]);

  if (disabled === true) return children;
  if (mountNode === null) return null;
  return createPortal(children, mountNode);
}

/**
 * Keeps a node in the tree until its exit animation has actually finished. The
 * timing logic is the core's `createPresence` (one frame for the transition to
 * exist, `getAnimations()`, a one second ceiling); this is only its React
 * lifecycle.
 *
 * The node is needed to ask what is animating, so the child gets a ref — composed
 * with whatever ref the consumer already put on it.
 */

import { createPresence, type Presence as PresenceCore } from "@standarui/core";
import {
  cloneElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import { flushSync } from "react-dom";
import { composeRefs } from "./compose-refs";
import { useSafeLayoutEffect } from "./use-safe-layout-effect";

export interface UsePresenceOptions {
  /** The machine's open state. */
  readonly present: boolean;
  /** Skip the wait — reduced motion, or a first render. */
  readonly immediate?: boolean | undefined;
  readonly timeout?: number | undefined;
}

export interface PresenceApi {
  /** True while the node must stay in the tree, exit animation included. */
  readonly present: boolean;
  readonly exiting: boolean;
  readonly ref: (node: HTMLElement | null) => void;
}

interface PresenceState {
  readonly present: boolean;
  readonly exiting: boolean;
}

export function usePresence(options: UsePresenceOptions): PresenceApi {
  const [state, setState] = useState<PresenceState>(() => ({
    present: options.present,
    exiting: false,
  }));
  const node = useRef<HTMLElement | null>(null);
  const latest = useRef(options);
  latest.current = options;

  const settling = useRef(false);
  const presence = useRef<PresenceCore | null>(null);
  presence.current ??= createPresence({
    // Outside the layout effect an exit ends on the core's own clock — the
    // `finished` microtask, the frame that found nothing animating, or the
    // timeout — and each is committed synchronously. The first is the one that
    // matters: it runs before the frame the exit ended in is painted, and a
    // deferred render would paint that frame with the node back at its resting
    // style — full height, full opacity, for any exit declared without a fill
    // mode (R127). Inside the layout effect (`immediate`, no node) React is
    // already committing and flushSync may not run.
    onExitComplete: (): void => {
      const next: PresenceState = { present: false, exiting: false };
      if (settling.current) setState(next);
      else flushSync(() => setState(next));
    },
    // Getters, so a `reducedMotion` that flips mid-session is honoured by the very
    // next exit instead of the one after the component remounts.
    get immediate(): boolean | undefined {
      return latest.current.immediate;
    },
    get timeout(): number | undefined {
      return latest.current.timeout;
    },
  });
  const instance = presence.current;

  useSafeLayoutEffect(() => {
    settling.current = true;
    try {
      instance.setPresent(options.present, node.current);
    } finally {
      settling.current = false;
    }
    setState({ present: instance.isPresent(), exiting: instance.isExiting() });
  }, [instance, options.present]);

  useSafeLayoutEffect(() => () => instance.destroy(), [instance]);

  const ref = useCallback((next: HTMLElement | null): void => {
    node.current = next;
  }, []);

  return useMemo(
    () => ({ present: state.present, exiting: state.exiting, ref }),
    [state.present, state.exiting, ref],
  );
}

export interface PresenceProps extends UsePresenceOptions {
  /** Keeps the node rendered while closed — the consumer hides it in CSS. */
  readonly keepMounted?: boolean | undefined;
  readonly children: ReactElement;
}

export function Presence(props: PresenceProps): ReactNode {
  const { children, keepMounted, ...options } = props;
  const presence = usePresence(options);

  if (!presence.present && keepMounted !== true) return null;

  const childRef = (children.props as { ref?: Ref<HTMLElement> }).ref;
  return cloneElement(children, { ref: composeRefs(presence.ref, childRef) } as object);
}

/**
 * The React half of the `ReactivityAdapter` contract. The interpreter stays in the
 * core; this file only says how a value is stored and how a change becomes a
 * render.
 *
 * One deliberate divergence from the roadmap line "bindable sur useState": with a
 * single interpreter created once, the set of bindables is only discovered while
 * `createService` runs, inside the first render — and hooks cannot be allocated
 * from there, because a lazily initialised ref makes the hook count differ
 * between StrictMode's two render passes ("rendered fewer hooks than expected").
 * Zag can put a `useState` behind every bindable precisely because it replays the
 * whole machine setup on every render, which is what the "un seul interpréteur
 * dans le core" decision rules out.
 *
 * So a cell is a plain mutable variable owned by the component, and React state
 * carries nothing but a version counter, bumped once per settled batch. That is
 * strictly fewer renders than one `setState` per context key, and the value the
 * component reads through `connect` is always the one the machine just wrote —
 * there is no store to tear against, because the store belongs to the component
 * doing the reading.
 */

import {
  arrayEquals,
  type Bindable,
  type BindableParams,
  createBindable,
  invariant,
  type ReactivityAdapter,
} from "@standarui/core";
import { useRef, useState } from "react";

const MAX_PASSES = 50;

interface Watcher {
  readonly deps: () => readonly unknown[];
  readonly effect: VoidFunction;
  last: readonly unknown[];
}

export interface ReactivityHandle {
  readonly adapter: ReactivityAdapter;
  /** Runs `machine.watch` until the graph settles. Called after every commit. */
  runWatchers(): void;
  /** Runs what the core registered through `onCleanup`, newest first. */
  runCleanups(): void;
}

const increment = (version: number): number => version + 1;

export function createReactivity(scheduleRender: VoidFunction): ReactivityHandle {
  const watchers: Watcher[] = [];
  const cleanups: VoidFunction[] = [];
  let depth = 0;
  let dirty = false;

  /**
   * Synchronous at depth 0 rather than deferred to a microtask: React 19
   * auto-batches every context there is, so a microtask would buy no coalescing
   * that React does not already do — it would only add a turn of latency and put
   * the write out of reach of `flushSync`.
   */
  const notify = (): void => {
    dirty = true;
    if (depth > 0) return;
    dirty = false;
    scheduleRender();
  };

  const adapter: ReactivityAdapter = {
    bindable: <V>(init: () => BindableParams<V>): Bindable<V> =>
      createBindable(init, (initial) => {
        let value = initial;
        return {
          get: (): V => value,
          set: (next: V): void => {
            value = next;
            notify();
          },
        };
      }),

    memo: <V>(compute: () => V, deps: () => readonly unknown[]): (() => V) => {
      let cache: { deps: readonly unknown[]; value: V } | undefined;
      return (): V => {
        const next = deps();
        if (cache === undefined || !arrayEquals(cache.deps, next)) {
          cache = { deps: next, value: compute() };
        }
        return cache.value;
      };
    },

    // Registration records the current deps without firing: a watcher reacts to a
    // change, it does not replay the initial state.
    track: (deps: () => readonly unknown[], effect: VoidFunction): void => {
      watchers.push({ deps, effect, last: deps() });
    },

    batch: (fn: VoidFunction): void => {
      depth += 1;
      try {
        fn();
      } finally {
        depth -= 1;
        if (depth === 0 && dirty) {
          dirty = false;
          scheduleRender();
        }
      }
    },

    onCleanup: (dispose: VoidFunction): void => {
      cleanups.push(dispose);
    },
  };

  return {
    adapter,

    runWatchers(): void {
      let passes = 0;
      let changed = true;
      // A watcher that writes context can make another watcher's deps stale in the
      // same commit; settling here rather than waiting for the next render keeps a
      // derived value from being one frame behind the value it derives from.
      while (changed) {
        changed = false;
        for (const watcher of watchers) {
          const next = watcher.deps();
          if (arrayEquals(watcher.last, next)) continue;
          watcher.last = next;
          changed = true;
          watcher.effect();
        }
        passes += 1;
        invariant(passes <= MAX_PASSES, `watchers did not settle after ${MAX_PASSES} passes`);
      }
    },

    // Kept rather than emptied: StrictMode unmounts and remounts the same handle,
    // and the cleanups the core registered (its `stop`, which is idempotent) have
    // to still be there for the second unmount.
    runCleanups(): void {
      for (let index = cleanups.length - 1; index >= 0; index--) cleanups[index]?.();
    },
  };
}

export function useReactivity(): ReactivityHandle {
  const [, setVersion] = useState(0);
  const handle = useRef<ReactivityHandle | null>(null);
  // `createReactivity` performs no side effect, so StrictMode's second render pass
  // finding the ref already filled is the whole point rather than a hazard.
  handle.current ??= createReactivity(() => setVersion(increment));
  return handle.current;
}

/**
 * A part component takes two kinds of prop on one object: the machine's, and
 * whatever the consumer wants on the element. This splits them by an explicit key
 * list — explicit because a heuristic ("anything the machine declares") would
 * silently swallow a new DOM attribute the day someone adds a machine prop with
 * the same name.
 */

export function splitProps<T extends object, K extends keyof T>(
  props: T,
  keys: readonly K[],
): [Pick<T, K>, Omit<T, K>] {
  const owned = {} as Pick<T, K>;
  const rest = { ...props } as Record<string, unknown>;
  for (const key of keys) {
    if (!(key in props)) continue;
    owned[key] = props[key];
    delete rest[key as string];
  }
  return [owned, rest as Omit<T, K>];
}

import { type RefObject, useEffect } from "react";
import { trackInputModality } from "./nav";

export function useInputModality(node: RefObject<HTMLElement | null>): void {
  useEffect(() => {
    const doc = node.current?.ownerDocument;
    if (doc === undefined) return;
    return trackInputModality(doc);
  }, [node]);
}

/**
 * The whole React lifecycle of a machine, in one hook.
 *
 * `createService` runs during render on purpose: the core guarantees it performs
 * no side effect, and that is what lets `connect` be called in the same render
 * pass and produce the markup the server would have produced. Everything that
 * actually happens — effects, entry actions — waits for `start()` in a layout
 * effect, and `stop()` undoes exactly that, so StrictMode's mount/unmount/mount
 * settles back on the same state.
 */

import {
  createService,
  type Machine,
  type MachineSchema,
  type PartIdOverrides,
  type PropsInput,
  type RootNode,
  type Service,
} from "@standarui/core";
import { useId, useRef } from "react";
import { useRootNode } from "./environment";
import { useReactivity } from "./reactivity";
import { useSafeLayoutEffect } from "./use-safe-layout-effect";

export interface MachineRuntimeProps {
  /**
   * Defaults to `useId()`. Pass one when the markup has to match a server render.
   * It also becomes the root part's DOM id — see the note in `useMachine`.
   */
  readonly id?: string | undefined;
  /** Overrides for individual part ids, keyed by part name. */
  readonly ids?: PartIdOverrides | undefined;
  /** Defaults to the nearest `EnvironmentProvider`, then to the document. */
  readonly getRootNode?: (() => RootNode) | undefined;
}

export type UseMachineProps<S extends MachineSchema> = PropsInput<S> & MachineRuntimeProps;

export function useMachine<S extends MachineSchema>(
  machine: Machine<S>,
  props: UseMachineProps<S>,
): Service<S> {
  const fallbackId = useId();
  const reactivity = useReactivity();
  const inheritedRootNode = useRootNode();

  // Written during render, and it has to be: `connect` reads props through the
  // service in this very pass, so a value parked in an effect would render one
  // pass stale. The ref belongs to this component and nothing else reads it, which
  // is what keeps a discarded concurrent render from being observable.
  const latest = useRef(props);
  latest.current = props;

  const service = useRef<Service<S> | null>(null);
  service.current ??= createService(machine, reactivity.adapter, {
    id: props.id ?? fallbackId,
    // An `id` arriving from outside is a DOM id, not a scope id. A machine root
    // used as another part's `render` target is handed that part's own id, and it
    // has to wear it: the composer looks its element up by that id and finds
    // nothing if the root quietly derives `{component}:{id}:root` instead. Seeding
    // `ids.root` makes both lookups land on the same element — the composer finds
    // it, and this machine still finds itself. An explicit `ids` still wins.
    ids: props.id === undefined ? props.ids : { root: props.id, ...props.ids },
    getRootNode: props.getRootNode ?? inheritedRootNode,
    props: (): PropsInput<S> => latest.current as PropsInput<S>,
  });
  const instance = service.current;

  useSafeLayoutEffect(() => {
    instance.start();
    return () => {
      instance.stop();
      reactivity.runCleanups();
    };
  }, [instance, reactivity]);

  // No dependency array: a prop change and a context write both reach the machine
  // through a commit, so "after every commit" is exactly when a watcher is due.
  // Before paint, like `start`, so a machine that reacts to a controlled value
  // coming down never shows the frame it was still out of sync for.
  useSafeLayoutEffect(() => {
    reactivity.runWatchers();
  });

  return instance;
}

/**
 * Composition, in the Base UI shape (`render`) with the Radix spelling
 * (`asChild`) kept as an alias — both end at the same place, and neither is worth
 * making somebody relearn.
 *
 * The merge order is the core's `mergeProps` rule, and it is the whole point:
 * the consumer's values win, but the consumer's handlers run *first*, so their
 * `preventDefault()` is a real veto over the machine's own handler.
 */

import { type AnyProps, mergeProps, toKebabCase } from "@standarui/core";
import {
  Children,
  cloneElement,
  createElement,
  type ElementType,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useMemo,
  useRef,
} from "react";
import { composeRefs } from "./compose-refs";
import { useSafeLayoutEffect } from "./use-safe-layout-effect";

/**
 * Handed the part's props to place itself. It must forward `props.ref` to the
 * element it renders: the part's core styles are written on that node by the
 * CSSOM after mount, and a function that drops the ref leaves them unwritten.
 */
export type RenderFunction = (props: AnyProps) => ReactNode;

/** An element to clone, or a function handed the props to place itself. */
export type RenderProp = ReactElement | RenderFunction;

export interface RenderableProps {
  readonly render?: RenderProp | undefined;
  readonly asChild?: boolean | undefined;
}

export interface RenderOptions extends RenderableProps {
  /** What the part renders when nothing is substituted. */
  readonly element: ElementType;
  /**
   * The prop getter's output, already normalized. Typed as `object` rather than a
   * record: `normalizeProps.button(…)` hands back React's own props type, which
   * has no index signature and would not satisfy a `Record<string, unknown>`.
   */
  readonly props: object;
  /**
   * What the consumer put on the part — `className`, `ref`, their own `onClick`.
   * Merged here rather than by each component so the one cast this needs lives in
   * one place, and so the ordering rule is stated once.
   */
  readonly elementProps?: object | undefined;
  readonly children?: ReactNode;
}

function onlyElement(children: ReactNode): ReactElement | null {
  const child = Children.only(children);
  return isValidElement(child) ? child : null;
}

type Written = readonly [text: string, applied: string];

const NO_WRITES: ReadonlyMap<string, Written> = new Map();

const SIDE = /-(?:top|right|bottom|left|block|inline|x|y)(?:-(?:start|end))?(?=-width$|$)/;

function propertyName(key: string): string {
  return key.startsWith("--") ? key : toKebabCase(key);
}

function styleProperties(style: unknown): string[] {
  return typeof style === "object" && style !== null ? Object.keys(style).map(propertyName) : [];
}

function sharesDeclaration(core: string, consumer: string): boolean {
  return core === consumer || (!consumer.startsWith("--") && core === consumer.replace(SIDE, ""));
}

export function useRender(options: RenderOptions): ReactNode {
  const { render, asChild, element, props, elementProps, children } = options;

  const target = asChild === true ? onlyElement(children) : (render ?? null);
  const substituted = typeof target === "object" && target !== null ? target.props : undefined;

  const node = useRef<unknown>(null);

  // **`ref` is chained, not overwritten, and it is the one prop that has to be.**
  // `mergeProps` is later-wins, and React 19 carries `ref` as a plain prop — so a
  // consumer putting their own ref on a part silently *replaced* the part's, and
  // whatever the part needed the node for stopped happening. It was found through
  // the accordion, where the part's ref is what writes `hidden="until-found"`:
  // pass a ref and Ctrl+F quietly stopped revealing the panel. Chained here rather
  // than in each component, because the failure is silent and every part is
  // exposed to it. Memoised on the two refs: a fresh callback every render would
  // detach and re-attach on each pass, tearing down anything a consumer installed
  // in their own callback. The node the core's styles are written on is captured by
  // an internal ref chained in the same memo, so its identity is as stable.
  const machineRef = (props as AnyProps)["ref"] as Ref<never> | undefined;
  const consumerRef = (elementProps as AnyProps | undefined)?.["ref"] as Ref<never> | undefined;
  const substitutedRef = (substituted as AnyProps | undefined)?.["ref"] as Ref<never> | undefined;
  const chained = useMemo(
    () => composeRefs(node as Ref<never>, machineRef, consumerRef, substitutedRef),
    [machineRef, consumerRef, substitutedRef],
  );

  // The machine's props first, then the consumer's: later wins for values, and
  // handlers run in reverse — theirs before the machine's, which is what makes
  // `preventDefault()` a veto rather than a suggestion. The machine's `style` is
  // taken out first: it is written on the node by the CSSOM below, never rendered.
  const { style: machineStyle, ...machineProps } = props as AnyProps;
  const base = mergeProps(machineProps, elementProps as AnyProps | undefined);
  const own = { ...base, ref: chained };

  const consumerProperties = [
    ...styleProperties(base["style"]),
    ...styleProperties((substituted as AnyProps | undefined)?.["style"]),
  ];
  const written = useRef<ReadonlyMap<string, Written>>(NO_WRITES);
  useSafeLayoutEffect(() => {
    const style = (node.current as Partial<ElementCSSInlineStyle> | null)?.style;
    if (typeof style?.setProperty !== "function") {
      written.current = NO_WRITES;
      return;
    }
    const isConsumers = (name: string): boolean =>
      consumerProperties.some((property) => sharesDeclaration(name, property));
    const next = new Map<string, Written>();
    for (const [key, value] of Object.entries(machineStyle ?? {})) {
      const name = propertyName(key);
      if (value == null || (typeof value !== "string" && !name.startsWith("--"))) continue;
      if (isConsumers(name)) continue;
      const text = String(value);
      const previous = written.current.get(name);
      if (previous?.[0] !== text || style.getPropertyValue(name) !== previous[1]) {
        style.setProperty(name, text);
      }
      next.set(name, [text, style.getPropertyValue(name)]);
    }
    for (const [name, [, applied]] of written.current) {
      if (!next.has(name) && !isConsumers(name) && style.getPropertyValue(name) === applied) {
        style.removeProperty(name);
      }
    }
    written.current = next;
  });

  if (target === null) return createElement(element, own, children);

  if (typeof target === "function") return target({ ...own, children });

  // In `asChild` the target *is* the children, so passing them down would nest the
  // element inside itself; `render` keeps the part's children unless the
  // substituted element brought its own. `mergeProps` ignores `undefined`, which
  // is what makes the first argument a defaulting one. The refs are the exception
  // to later-wins: the substituted element's own ref is chained after the part's.
  const placed = mergeProps(
    { children: asChild === true ? undefined : children },
    own,
    substituted as AnyProps,
  );
  return cloneElement(target, { ...placed, ref: chained } as object);
}

/**
 * `useLayoutEffect` in the browser, `useEffect` on the server.
 *
 * The machine's effects install listeners, move focus and read geometry; running
 * them after paint would show a frame of the un-managed state. React warns about
 * `useLayoutEffect` during SSR, hence the swap — the `typeof` guard tests for a
 * global, it never reads the DOM, so the "no document outside effects" rule is
 * intact.
 */

import { useEffect, useLayoutEffect } from "react";

export const useSafeLayoutEffect: typeof useEffect =
  typeof document === "undefined" ? useEffect : useLayoutEffect;

import { createVirtualIndex, getScrollTarget, type VirtualIndex } from "@standarui/core";
import {
  type FocusEvent as ReactFocusEvent,
  useCallback,
  useEffect,
  useReducer,
  useRef,
} from "react";
import { useSafeLayoutEffect } from "./use-safe-layout-effect";

export type VirtualizerAlign = "start" | "center" | "end" | "nearest";

export interface VirtualizerScrollToOptions {
  readonly align?: VirtualizerAlign | undefined;
}

export interface UseVirtualizerOptions {
  readonly count: number;
  readonly estimateSize: (index: number) => number;
  readonly getScrollElement: () => HTMLElement | null;
  readonly orientation?: "vertical" | "horizontal" | undefined;
  readonly overscan?: number | undefined;
  readonly paddingStart?: number | undefined;
  readonly gap?: number | undefined;
  readonly getItemKey?: ((index: number) => string | number) | undefined;
  readonly initialSize?: number | undefined;
}

export interface VirtualizerItem {
  readonly index: number;
  readonly key: string | number;
  readonly start: number;
  readonly size: number;
}

export interface VirtualizerContainerProps {
  readonly ref: (node: HTMLElement | null) => VoidFunction;
  readonly "data-sui-virtual": "";
  readonly "data-orientation": "vertical" | "horizontal";
}

export interface VirtualizerItemProps {
  readonly ref: (node: HTMLElement | null) => VoidFunction;
  readonly onFocus: (event: ReactFocusEvent<HTMLElement>) => void;
  readonly onBlur: (event: ReactFocusEvent<HTMLElement>) => void;
  readonly "data-index": number;
  readonly "data-sui-virtual-item": "";
}

export interface Virtualizer {
  readonly items: readonly VirtualizerItem[];
  readonly totalSize: number;
  scrollToIndex(index: number, options?: VirtualizerScrollToOptions): void;
  getContainerProps(): VirtualizerContainerProps;
  getItemProps(index: number): VirtualizerItemProps;
}

const SIZE = "--sui-virtual-size";
const START = "--sui-virtual-start";
const ITEM = "[data-sui-virtual-item]";
const DEFAULT_OVERSCAN = 3;

type Key = string | number;

interface Binding {
  readonly ref: (node: HTMLElement | null) => VoidFunction;
  readonly onFocus: (event: ReactFocusEvent<HTMLElement>) => void;
  readonly onBlur: (event: ReactFocusEvent<HTMLElement>) => void;
}

const identity = (row: number): number => row;

interface Committed {
  start: number;
  end: number;
}

interface Target {
  index: number;
  align: VirtualizerAlign;
  expected: number;
}

function write(node: HTMLElement, name: string, value: string): void {
  if (node.style.getPropertyValue(name) !== value) node.style.setProperty(name, value);
}

function createController(
  latest: { current: UseVirtualizerOptions },
  bump: () => void,
): Controller {
  let index: VirtualIndex | null = null;
  let configured = "";
  let oriented = "";
  let counted = 0;
  const measured = new Map<Key, number>();
  const nodes = new Map<Key, HTMLElement>();
  const keys = new WeakMap<Element, Key>();
  const bindings = new Map<Key, Binding>();
  const committed: Committed = { start: 0, end: -1 };
  let element: HTMLElement | null = null;
  let container: HTMLElement | null = null;
  let observer: ResizeObserver | null = null;
  let detachElement: VoidFunction | null = null;
  let frame = 0;
  let scrollOffset = 0;
  let viewportSize = 0;
  let focusedKey: Key | null = null;
  let focusedRow = -1;
  let focusTarget: EventTarget | null = null;
  let blurFrame = 0;
  let blurWindow: Window | null = null;
  let target: Target | null = null;

  const horizontal = (): boolean => latest.current.orientation === "horizontal";

  const keyOf = (row: number): Key => (latest.current.getItemKey ?? identity)(row);

  function rowOf(node: Element): number | null {
    const row = Number(node.getAttribute("data-index"));
    return Number.isInteger(row) ? row : null;
  }

  function readOffset(): number {
    if (element === null) return scrollOffset;
    return horizontal() ? Math.abs(element.scrollLeft) : element.scrollTop;
  }

  function writeOffset(value: number): void {
    if (element === null) return;
    if (!horizontal()) {
      element.scrollTop = value;
      return;
    }
    const rtl = element.ownerDocument.defaultView?.getComputedStyle(element).direction === "rtl";
    element.scrollLeft = rtl ? -value : value;
  }

  function readViewport(): number {
    if (element === null) return viewportSize;
    return horizontal() ? element.clientWidth : element.clientHeight;
  }

  function replay(virtual: VirtualIndex, count: number): void {
    if (latest.current.getItemKey === undefined) {
      for (const [key, size] of measured) {
        if (typeof key === "number" && key < count) virtual.setSize(key, size);
      }
      return;
    }
    if (!Number.isFinite(count)) return;
    for (let row = 0; row < count; row++) {
      const size = measured.get(keyOf(row));
      if (size !== undefined) virtual.setSize(row, size);
    }
  }

  // A key that left the list keeps its size so that it lands where it was if it
  // comes back; past twice the count, only the keys present now are kept.
  function prune(): void {
    const { count, getItemKey } = latest.current;
    if (getItemKey === undefined || !Number.isFinite(count) || measured.size <= 2 * count) return;
    const live = new Map<Key, number>();
    for (let row = 0; row < count; row++) {
      const key = keyOf(row);
      const size = measured.get(key);
      if (size !== undefined) live.set(key, size);
    }
    measured.clear();
    for (const [key, size] of live) measured.set(key, size);
  }

  function ensure(): VirtualIndex {
    const { count, paddingStart = 0, gap = 0 } = latest.current;
    const orientation = horizontal() ? "horizontal" : "vertical";
    const key = `${paddingStart}|${gap}|${orientation}`;
    if (index === null || configured !== key) {
      if (oriented !== orientation) measured.clear();
      oriented = orientation;
      index = createVirtualIndex({
        count,
        estimateSize: (row) => latest.current.estimateSize(row),
        paddingStart,
        gap,
      });
      configured = key;
      replay(index, count);
    }
    if (count < counted && latest.current.getItemKey === undefined) {
      for (const key of measured.keys()) {
        if (typeof key === "number" && key >= count) measured.delete(key);
      }
    }
    counted = count;
    index.setCount(count);
    return index;
  }

  function range(): ReturnType<VirtualIndex["range"]> {
    return ensure().range(viewportSize, scrollOffset, latest.current.overscan ?? DEFAULT_OVERSCAN);
  }

  function compare(): void {
    const next = range();
    if (next.startIndex !== committed.start || next.endIndex !== committed.end) bump();
  }

  function sync(): void {
    const virtual = ensure();
    for (const [key, node] of nodes) {
      const row = rowOf(node);
      const size = measured.get(key);
      if (row !== null && size !== undefined) virtual.setSize(row, size);
    }
    if (container !== null) write(container, SIZE, `${virtual.totalSize()}px`);
    for (const node of nodes.values()) {
      const row = rowOf(node);
      if (row !== null) write(node, START, `${virtual.offsetOf(row)}px`);
    }
  }

  function retarget(): void {
    if (target === null) return;
    const virtual = ensure();
    const to = getScrollTarget(virtual, latest.current.count, target.index, {
      viewportSize,
      scrollOffset: readOffset(),
      align: target.align,
    });
    if (to === null) {
      target = null;
      return;
    }
    const max = Math.max(0, virtual.totalSize() - viewportSize);
    const wanted = Math.max(0, Math.min(to, max));
    if (Math.abs(wanted - readOffset()) <= 1) return;
    writeOffset(wanted);
    scrollOffset = readOffset();
    target.expected = scrollOffset;
  }

  function measure(rows: readonly (readonly [Key, number, number])[], resized: boolean): void {
    const virtual = ensure();
    const offset = readOffset();
    if (target !== null && Math.abs(offset - target.expected) > 1.5) target = null;
    const inside = rows.filter(([, row]) => row < latest.current.count);
    for (const [key, , size] of inside) measured.set(key, size);
    prune();
    const changes = inside.filter(([, row, size]) => virtual.sizeOf(row) !== size);
    let delta = 0;
    for (const [, row, size] of changes) {
      if (virtual.offsetOf(row) < offset) delta += size - virtual.sizeOf(row);
    }
    for (const [, row, size] of changes) virtual.setSize(row, size);
    if (resized) viewportSize = readViewport();
    sync();
    if (delta !== 0) writeOffset(offset + delta);
    scrollOffset = readOffset();
    if (target !== null) target.expected = scrollOffset;
    if (target !== null && changes.length > 0) retarget();
    compare();
  }

  function onResize(entries: readonly ResizeObserverEntry[]): void {
    if (element === null) return;
    const rows: (readonly [Key, number, number])[] = [];
    let resized = false;
    for (const entry of entries) {
      if (entry.target === element) {
        resized = true;
        continue;
      }
      const key = keys.get(entry.target);
      const row = key === undefined ? null : rowOf(entry.target);
      if (key === undefined || row === null) continue;
      const box = entry.borderBoxSize?.[0];
      const node = entry.target as HTMLElement;
      const size = horizontal()
        ? (box?.inlineSize ?? node.offsetWidth)
        : (box?.blockSize ?? node.offsetHeight);
      rows.push([key, row, size]);
    }
    measure(rows, resized);
  }

  function onScroll(): void {
    if (frame !== 0 || element === null) return;
    const win = element.ownerDocument.defaultView;
    if (win === null) return;
    frame = win.requestAnimationFrame(() => {
      frame = 0;
      scrollOffset = readOffset();
      if (target !== null && Math.abs(scrollOffset - target.expected) > 1.5) target = null;
      compare();
    });
  }

  function setFocused(key: Key | null, row: number): void {
    const before = focusedKey === null ? null : focusedRow;
    const changed = key !== focusedKey;
    focusedKey = key;
    focusedRow = row;
    if (!changed) return;
    const outside = (at: number | null): boolean =>
      at !== null && (at < committed.start || at > committed.end);
    if (outside(before) || outside(key === null ? null : row)) bump();
  }

  function cancelBlur(): void {
    if (blurFrame !== 0) blurWindow?.cancelAnimationFrame(blurFrame);
    blurFrame = 0;
  }

  function attach(next: HTMLElement): VoidFunction {
    const win = next.ownerDocument.defaultView;
    next.addEventListener("scroll", onScroll, { passive: true });
    if (win !== null && "ResizeObserver" in win) {
      observer = new win.ResizeObserver((entries) => onResize(entries));
      observer.observe(next);
      for (const node of nodes.values()) observer.observe(node);
    }
    const active = next.ownerDocument.activeElement;
    const holder = active === null ? null : active.closest(ITEM);
    const heldKey = holder === null ? undefined : keys.get(holder);
    if (holder !== null && heldKey !== undefined) {
      focusedKey = heldKey;
      focusedRow = rowOf(holder) ?? -1;
      focusTarget = active;
    }
    return () => {
      next.removeEventListener("scroll", onScroll);
      observer?.disconnect();
      observer = null;
      if (frame !== 0) win?.cancelAnimationFrame(frame);
      frame = 0;
    };
  }

  function bind(release: boolean): void {
    const next = latest.current.getScrollElement();
    if (next === element) return;
    if (next === null && !release) return;
    detachElement?.();
    detachElement = null;
    element = next;
    if (next === null) return;
    detachElement = attach(next);
    viewportSize = readViewport();
    scrollOffset = readOffset();
    compare();
  }

  const containerRef = (node: HTMLElement | null): VoidFunction => {
    container = node;
    if (node !== null) write(node, SIZE, `${ensure().totalSize()}px`);
    return () => {
      if (container === node) container = null;
    };
  };

  function binding(row: number): Binding {
    const key = keyOf(row);
    let found = bindings.get(key);
    if (found === undefined) {
      found = {
        ref: (node) => {
          if (node === null) return () => {};
          nodes.set(key, node);
          keys.set(node, key);
          observer?.observe(node);
          return () => {
            observer?.unobserve(node);
            if (nodes.get(key) === node) nodes.delete(key);
            keys.delete(node);
          };
        },
        onFocus: (event) => {
          cancelBlur();
          focusTarget = event.target;
          setFocused(key, rowOf(event.currentTarget) ?? -1);
        },
        onBlur: (event) => {
          const doc = event.currentTarget.ownerDocument;
          const win = doc.defaultView;
          if (win === null) return;
          cancelBlur();
          blurWindow = win;
          blurFrame = win.requestAnimationFrame(() => {
            blurFrame = 0;
            if (focusedKey !== key) return;
            if (doc.activeElement !== null && doc.activeElement === focusTarget) return;
            setFocused(null, -1);
          });
        },
      };
      bindings.set(key, found);
    }
    return found;
  }

  function pinned(): number | null {
    if (focusedKey === null) return null;
    const { count, getItemKey } = latest.current;
    if (getItemKey === undefined) {
      if (typeof focusedKey !== "number" || focusedKey >= count) return null;
      focusedRow = focusedKey;
      return focusedKey;
    }
    if (focusedRow >= 0 && focusedRow < count && getItemKey(focusedRow) === focusedKey) {
      return focusedRow;
    }
    for (let row = 0; row < count; row++) {
      if (getItemKey(row) === focusedKey) {
        focusedRow = row;
        return row;
      }
    }
    return null;
  }

  return {
    ensure,
    range,
    bind,
    sync,
    compare,
    containerRef,
    itemProps(row) {
      const { ref, onFocus, onBlur } = binding(row);
      return { ref, onFocus, onBlur, "data-index": row, "data-sui-virtual-item": "" };
    },
    pinned,
    commit(start, end, mounted) {
      committed.start = start;
      committed.end = end;
      if (focusedKey !== null && !mounted.includes(focusedKey)) {
        const active = (element ?? container)?.ownerDocument.activeElement ?? null;
        if (active === null || active.closest(ITEM) === null) {
          focusedKey = null;
          focusedRow = -1;
        }
      }
      if (bindings.size > mounted.length) {
        const live = new Set(mounted);
        for (const key of bindings.keys()) if (!live.has(key)) bindings.delete(key);
      }
    },
    initialize(size) {
      if (element === null) viewportSize = size;
    },
    scrollToIndex(row, options) {
      if (element === null) return;
      const align = options?.align ?? "nearest";
      const virtual = ensure();
      const to = getScrollTarget(virtual, latest.current.count, row, {
        viewportSize,
        scrollOffset: readOffset(),
        align,
      });
      if (to === null) return;
      const max = Math.max(0, virtual.totalSize() - viewportSize);
      writeOffset(Math.max(0, Math.min(to, max)));
      scrollOffset = readOffset();
      target = { index: row, align, expected: scrollOffset };
      compare();
    },
    destroy() {
      detachElement?.();
      detachElement = null;
      element = null;
      cancelBlur();
    },
  };
}

interface Controller {
  ensure(): VirtualIndex;
  range(): ReturnType<VirtualIndex["range"]>;
  bind(release: boolean): void;
  sync(): void;
  compare(): void;
  containerRef(node: HTMLElement | null): VoidFunction;
  itemProps(row: number): VirtualizerItemProps;
  pinned(): number | null;
  commit(start: number, end: number, mounted: readonly Key[]): void;
  initialize(size: number): void;
  scrollToIndex(row: number, options?: VirtualizerScrollToOptions): void;
  destroy(): void;
}

export function useVirtualizer(options: UseVirtualizerOptions): Virtualizer {
  const latest = useRef(options);
  latest.current = options;
  const [, bump] = useReducer((version: number) => version + 1, 0);
  const controller = useRef<Controller | null>(null);
  controller.current ??= createController(latest, bump);
  const current = controller.current;

  const virtual = current.ensure();
  current.initialize(options.initialSize ?? 0);
  const visible = current.range();
  const pinned = current.pinned();
  const getItemKey = options.getItemKey ?? identity;

  const rows: number[] = [];
  if (pinned !== null && pinned < options.count && pinned < visible.startIndex) rows.push(pinned);
  for (let row = visible.startIndex; row <= visible.endIndex; row++) rows.push(row);
  if (pinned !== null && pinned < options.count && pinned > visible.endIndex) rows.push(pinned);

  const items = rows.map(
    (row): VirtualizerItem => ({
      index: row,
      key: getItemKey(row),
      start: virtual.offsetOf(row),
      size: virtual.sizeOf(row),
    }),
  );

  useSafeLayoutEffect(() => {
    current.commit(
      visible.startIndex,
      visible.endIndex,
      items.map((item) => item.key),
    );
    current.bind(false);
    current.sync();
    current.compare();
  });

  useEffect(() => {
    current.bind(true);
  });

  useSafeLayoutEffect(() => () => current.destroy(), [current]);

  const orientation = options.orientation ?? "vertical";
  const getContainerProps = useCallback(
    (): VirtualizerContainerProps => ({
      ref: current.containerRef,
      "data-sui-virtual": "",
      "data-orientation": orientation,
    }),
    [current, orientation],
  );

  return {
    items,
    totalSize: virtual.totalSize(),
    scrollToIndex: current.scrollToIndex,
    getContainerProps,
    getItemProps: current.itemProps,
  };
}
